{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const fail = msg => { process.stderr.write(`error: ${msg}\n`); process.exit(2) }
const mode = process.argv.slice(2)
if (mode.length !== 1 || !['merge', 'merge2', 'regions'].includes(mode[0])) fail('usage: cli.js merge|merge2|regions')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) { if (l === '%%%') docs.push([]); else docs[docs.length - 1].push(l) }
if (docs.length !== 3) fail('expected three parts separated by %%%')
const [mine, base, theirs] = docs

function changes(side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--)
    L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => { if (i > bs || j > ss) out.push({ who, bs, be: i, ss, se: j }) }
  while (i < n && j < m) {
    if (base[i] === side[j]) { flush(); i++; j++; bs = i; ss = j }
    else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const all = [...changes(mine, 0), ...changes(theirs, 1)]
all.sort((a, b) => a.bs - b.bs || a.who - b.who)

const out = []
let conflict = false
const sides = [mine, theirs]
const reg = []
let pos = 0, k = 0
while (k < all.length) {
  const c = all[k++]
  const group = [c]
  let end = c.be
  while (k < all.length && all[k].bs <= end) { group.push(all[k]); end = Math.max(end, all[k].be); k++ }
  if (c.bs > pos) reg.push({ stable: base.slice(pos, c.bs) })
  const start = c.bs
  if (group.length === 1) {
    reg.push({ lines: sides[c.who].slice(c.ss, c.se), kind: c.who ? 'theirs' : 'mine' })
  } else {
    const rep = who => {
      const g = group.filter(x => x.who === who)
      if (!g.length) return base.slice(start, end)
      const s = Math.min(...g.map(x => x.ss)) - (Math.min(...g.map(x => x.bs)) - start)
      const e = Math.max(...g.map(x => x.se)) + (end - Math.max(...g.map(x => x.be)))
      return sides[who].slice(s, e)
    }
    const m = rep(0), t = rep(1), b = base.slice(start, end)
    const eq = (x, y) => x.length === y.length && x.every((v, i) => v === y[i])
    if (eq(m, t)) reg.push({ lines: m, kind: 'both' })
    else if (eq(m, b)) reg.push({ lines: t, kind: 'theirs' })
    else if (eq(t, b)) reg.push({ lines: m, kind: 'mine' })
    else reg.push({ conflict: true, m, b, t })
  }
  pos = end
}
if (pos < base.length) reg.push({ stable: base.slice(pos) })

for (const r of reg) {
  if (r.stable) {
    if (mode[0] === 'regions') out.push(`stable ${r.stable.length}`); else out.push(...r.stable)
  } else if (r.conflict) {
    conflict = true
    if (mode[0] === 'regions') out.push(`conflict mine=${r.m.length} base=${r.b.length} theirs=${r.t.length}`)
    else {
      out.push('<<<<<<< mine', ...r.m)
      if (mode[0] === 'merge') out.push('||||||| base', ...r.b)
      out.push('=======', ...r.t, '>>>>>>> theirs')
    }
  } else if (mode[0] === 'regions') out.push(`${r.kind} ${r.lines.length}`)
  else out.push(...r.lines)
}
process.stdout.write(out.map(l => l + '\n').join(''))
process.exit(conflict ? 1 : 0)
